QItem item = QItem.item;   // 또는 static import

// 전체
List<Item> all = query.selectFrom(item).fetch();

// 조건
List<Item> cheap = query.selectFrom(item)
        .where(item.price.loe(10000))
        .fetch();

// 여러 조건 — and
List<Item> result = query.selectFrom(item)
        .where(item.itemName.like("%itemA%"),
               item.price.loe(10000))
        .fetch();

// 정렬과 페이징
List<Item> page = query.selectFrom(item)
        .where(item.price.goe(1000))
        .orderBy(item.price.desc(), item.itemName.asc())
        .offset(0)
        .limit(10)
        .fetch();

// 한 건
Item one = query.selectFrom(item)
        .where(item.id.eq(1L))
        .fetchOne();
